def run2(g,tpl,cellcol,els):
    g=np.array(g); out=g.copy(); n=0
    oh=max(r for r,_ in tpl)+1; ow=max(c for _,c in tpl)+1
    for r in range(g.shape[0]-oh+1):
        for c in range(g.shape[1]-ow+1):
            w=g[r:r+oh,c:c+ow]; ok=True
            for rr in range(oh):
                for cc in range(ow):
                    v=w[rr,cc]
                    if (rr,cc) in tpl:
                        if v!=cellcol: ok=False;break
                    elif v not in els: ok=False;break
                if not ok:break
            if ok:
                n+=1
                for rr,cc in tpl: out[r+rr,c+cc]=7
    return out,n
