def orients8(tp):
    pts=[(r,c) for r,c in tp]
    outs=[]
    for sy in (1,-1):
        for rot in range(4):
            q=[(sy*r,c) for r,c in pts]
            for _ in range(rot):
                q=[(c,-r) for r,c in q]
            m=min(q); n=frozenset((r-m[0],c-m[1]) for r,c in q)
            if n not in outs: outs.append(n)
    return outs
def analyze(i_,o_,label):
