def rot_shapes(tplr):
    base=np.zeros((6,6),int)
    for r,c in tplr: base[r,c]=1
    outs=[]
    for k in range(4):
        a=np.rot90(base,k)
        ys,xs=np.where(a==1)
        r0,c0=ys.min(),xs.min()
        outs.append(frozenset((int(r-r0),int(c-c0)) for r,c in zip(ys,xs)))
    b=base[:,::-1]
    for k in range(4):
        a=np.rot90(b,k)
        ys,xs=np.where(a==1)
        r0,c0=ys.min(),xs.min()
        outs.append(frozenset((int(r-r0),int(c-c0)) for r,c in zip(ys,xs)))
    return list(dict.fromkeys(outs))
def rot_matches(gi,tplr,allowed_else):
    rh=max(r for r,_ in tplr)+1; cw=max(c for _,c in tplr)+1
    H,Wd=gi.shape; res={}
    for si,s in enumerate(rot_shapes(tplr)):
        h=max(r for r,_ in s)+1; w=max(c for _,c in s)+1
        ms=[]
        for r in range(H-h+1):
            for c in range(Wd-w+1):
                win=gi[r:r+h,c:c+w]
                if all(win[rr,cc]==0 for rr,cc in s):
                    els=set(int(x) for x in win.flatten())-{0}
                    if els<=allowed_else: ms.append((r,c))
        res[si]=ms
    return res
